import type { KnowledgeGraph, NodeId } from "./graph.ts";

export type Position = { x: number; y: number };

const ITERATIONS = 300;
/** The side of the square the simulation runs in before normalization. */
const SIDE = 1;

/** Deterministic: same graph in, same positions out. Coordinates are
 * normalized to [0, 1] so the view scales them to the canvas. */
export function layout(graph: KnowledgeGraph): Map<NodeId, Position> {
  const ids = graph.nodes.map((n) => n.id).sort();
  const positions = new Map<NodeId, Position>();
  if (ids.length === 0) return positions;
  if (ids.length === 1) {
    positions.set(ids[0]!, { x: 0.5, y: 0.5 });
    return positions;
  }

  // Initial placement on a circle in id order: no Math.random, so the whole
  // simulation is a pure function of the graph.
  ids.forEach((id, i) => {
    const angle = (2 * Math.PI * i) / ids.length;
    positions.set(id, {
      x: SIDE / 2 + (SIDE / 2) * Math.cos(angle),
      y: SIDE / 2 + (SIDE / 2) * Math.sin(angle),
    });
  });

  const edges = graph.edges.filter(
    (e) => positions.has(e.from) && positions.has(e.to),
  );
  const k = Math.sqrt((SIDE * SIDE) / ids.length);

  for (let step = 0; step < ITERATIONS; step++) {
    const temperature = (SIDE / 10) * (1 - step / ITERATIONS);
    const disp = new Map<NodeId, Position>(
      ids.map((id) => [id, { x: 0, y: 0 }]),
    );

    for (let i = 0; i < ids.length; i++)
      for (let j = i + 1; j < ids.length; j++) {
        const a = ids[i]!;
        const b = ids[j]!;
        const { dx, dy, dist } = delta(positions, a, b, i, j);
        const force = (k * k) / dist;
        push(disp, a, (dx / dist) * force, (dy / dist) * force);
        push(disp, b, -(dx / dist) * force, -(dy / dist) * force);
      }

    for (const edge of edges) {
      const { dx, dy, dist } = delta(positions, edge.from, edge.to, 0, 1);
      const force = (dist * dist) / k;
      push(disp, edge.from, -(dx / dist) * force, -(dy / dist) * force);
      push(disp, edge.to, (dx / dist) * force, (dy / dist) * force);
    }

    for (const id of ids) {
      const p = positions.get(id)!;
      const d = disp.get(id)!;
      const len = Math.hypot(d.x, d.y) || 1;
      const scale = Math.min(len, temperature) / len;
      p.x += d.x * scale;
      p.y += d.y * scale;
    }
  }

  return normalize(positions);
}

/** Vector from `b` to `a`, with a floor on the distance and a deterministic
 * nudge when two nodes land exactly on top of each other. */
function delta(
  positions: Map<NodeId, Position>,
  a: NodeId,
  b: NodeId,
  i: number,
  j: number,
): { dx: number; dy: number; dist: number } {
  const pa = positions.get(a)!;
  const pb = positions.get(b)!;
  let dx = pa.x - pb.x;
  let dy = pa.y - pb.y;
  let dist = Math.hypot(dx, dy);
  if (dist < 1e-6) {
    dx = 1e-4 * (i + 1);
    dy = 1e-4 * (j + 1);
    dist = Math.hypot(dx, dy);
  }
  return { dx, dy, dist };
}

function push(disp: Map<NodeId, Position>, id: NodeId, dx: number, dy: number) {
  const d = disp.get(id)!;
  d.x += dx;
  d.y += dy;
}

/** Fit to [0, 1] on both axes independently; a degenerate axis collapses to
 * the middle rather than dividing by zero. */
function normalize(positions: Map<NodeId, Position>): Map<NodeId, Position> {
  const xs = [...positions.values()].map((p) => p.x);
  const ys = [...positions.values()].map((p) => p.y);
  const fit = (v: number, lo: number, hi: number) =>
    hi - lo < 1e-9 ? 0.5 : (v - lo) / (hi - lo);
  const [minX, maxX] = [Math.min(...xs), Math.max(...xs)];
  const [minY, maxY] = [Math.min(...ys), Math.max(...ys)];
  const out = new Map<NodeId, Position>();
  for (const [id, p] of positions)
    out.set(id, { x: fit(p.x, minX, maxX), y: fit(p.y, minY, maxY) });
  return out;
}
